body.script:
const xhttp = new XMLHttpRequest();
xhttp.onload = function() {
  const xml = this.responseXML;
  const dias = xml.getElementsByTagName("dia");
  let html = "";
  for(let i = 0; i < dias.length; i++) {
    const fecha     = dias[i].getAttribute("fecha");
    const tmax      = dias[i].getElementsByTagName("maxima")[0]?.textContent || "-";
    const tmin      = dias[i].getElementsByTagName("minima")[0]?.textContent || "-";
    const humedad   = dias[i].getElementsByTagName("HumedadRelativa")[0]?.textContent || "-";
    const viento    = dias[i].getElementsByTagName("VelocidadViento")[0]?.textContent || "-";
    const direccion = dias[i].getElementsByTagName("DireccionViento")[0]?.textContent || "-";
    html += `
${fecha}

 Máx: ${tmax}°C | Mín: ${tmin}°C

 Humedad: ${humedad}% | 💨 Viento: ${viento} km/h (${direccion})`;
  }
  document.getElementById("meteo").innerHTML = html;
};
xhttp.onerror = () => { document.getElementById("meteo").innerHTML = "Error CORS — ejecuta desde servidor local."; };
xhttp.open("GET", "http://www.aemet.es/xml/municipios/localidad_21041.xml");
xhttp.send();
